fajl.isecak:
const GRANICA_TELA = 1024;

function procitajTelo(req) {
  return new Promise((resolve, reject) => {
    let tekst = "";
    let preveliko = false;
    req.on("data", (deo) => {
      if (preveliko) return;
      tekst += deo;
      if (tekst.length > GRANICA_TELA) {
        preveliko = true;
        reject(new Error("telo je preveliko"));
      }
    });
    req.on("end", () => resolve(tekst));
    req.on("error", reject);
  });
}

fajl.ugradjena:
const http = require("http");
const soba = require("./soba");
const ventilator = require("./ventilator");

const state = { temperatura: 24, ukljucen: false, prikljucen: true };
const GRANICA_TELA = 1024;

function posalji(res, status, body) {
  res.writeHead(status, { "content-type": "application/json; charset=utf-8" });
  res.end(JSON.stringify(body));
}

function procitajTelo(req) {
  return new Promise((resolve, reject) => {
    let tekst = "";
    let preveliko = false;
    req.on("data", (deo) => {
      if (preveliko) return;
      tekst += deo;
      if (tekst.length > GRANICA_TELA) {
        preveliko = true;
        reject(new Error("telo je preveliko"));
      }
    });
    req.on("end", () => resolve(tekst));
    req.on("error", reject);
  });
}

async function obrada(req, res) {
  const putanja = req.url.split("?")[0];
  if (putanja === "/api/ventilator") {
    if (req.method !== "PUT") {
      posalji(res, 405, { greska: "metod nije dozvoljen" });
      return;
    }
    let telo;
    try {
      telo = JSON.parse(await procitajTelo(req));
    } catch {
      posalji(res, 400, { greska: "neispravno telo" });
      return;
    }
    const rezultat = ventilator.komanda({ state }, telo);
    posalji(res, rezultat.status, rezultat.body);
    return;
  }
  if (putanja !== "/api/soba") {
    posalji(res, 404, { greska: "nema putanje" });
    return;
  }
  if (req.method !== "GET") {
    posalji(res, 405, { greska: "metod nije dozvoljen" });
    return;
  }
  const rezultat = soba.citaj({ state });
  posalji(res, rezultat.status, rezultat.body);
}

const server = http.createServer(obrada);
server.listen(8787, () => {
  console.log("server sluša port 8787");
});

function teloJeRezim(telo) {
  if (!telo || typeof telo !== "object" || Array.isArray(telo)) return false;
  const kljucevi = Object.keys(telo);
  return typeof telo.ukljucen === "boolean" && kljucevi.every((kljuc) => kljuc === "ukljucen");
}

async function upisiCelinu(baza, ukljucen) {
  const veza = await baza.connect();
  try {
    await veza.query("UPDATE ventilator SET ukljucen = $1 WHERE id = 1", [ukljucen]);
    return null;
  } finally {
    veza.release();
  }
}

async function komanda(kontekst, telo) {
  if (!teloJeRezim(telo)) return { status: 400, body: { greska: "telo nije boolean rezim" } };
  if (telo.ukljucen && !kontekst.state.prikljucen) {
    return { status: 500, body: { greska: "ventilator nije prikljucen" } };
  }
  if (kontekst.state.baza) {
    if (!kontekst.db) return { status: 503, body: { greska: "baza nije pokrenuta" } };
    const greskaUpisa = await upisiCelinu(kontekst.db, telo.ukljucen);
    if (greskaUpisa) return greskaUpisa;
  }
  kontekst.state.ukljucen = telo.ukljucen;
  return { status: 200, body: { ukljucen: kontekst.state.ukljucen } };
}

module.exports = { komanda };

function teloJeRezim(telo) {
  if (!telo || typeof telo !== "object" || Array.isArray(telo)) return false;
  const kljucevi = Object.keys(telo);
  return typeof telo.ukljucen === "boolean" && kljucevi.every((kljuc) => kljuc === "ukljucen");
}

function nazivKomande(ukljucen) {
  if (ukljucen) return "ukljuci";
  return "iskljuci";
}

async function upisiCelinu(baza, ukljucen) {
  const veza = await baza.connect();
  try {
    await veza.query("UPDATE ventilator SET ukljucen = $1 WHERE id = 1", [ukljucen]);
    await veza.query("INSERT INTO istorija (komanda) VALUES ($1)", [nazivKomande(ukljucen)]);
    return null;
  } finally {
    veza.release();
  }
}

async function komanda(kontekst, telo) {
  if (!teloJeRezim(telo)) return { status: 400, body: { greska: "telo nije boolean rezim" } };
